    "caret": "^", "comma": ",", "colon": ":", "semicolon": ";", "slash": "/", "forward_slash": "/", "backslash": "\\",
    "apostrophe": "'", "quote": "\"", "quotes": "\"", "lparen": "(", "left_paren": "(", "open_paren": "(", "rparen": ")", "right_paren": ")",
